_BOOK = None
_LEAVES = None
_ACTIVE = None
_LAST_MODE = None


def _load():
    global _BOOK, _LEAVES
    if _BOOK is not None:
        return
    branches, diagrams = json.loads(zlib.decompress(base64.b85decode(_DATA)))
    _BOOK, _LEAVES = {}, {}
    for history, move in branches.items():
        board, heights = [0] * 42, [0] * 7
        for turn, char in enumerate(history):
            c = int(char) - 1
            board[(5 - heights[c]) * 7 + c] = 1 + turn % 2
            heights[c] += 1
        key = tuple(board)
        _BOOK[key] = int(move) - 1
        _BOOK.setdefault(_mirror(key), 7 - int(move))
    for rows in diagrams:
        diagram = ''.join(rows)
        key = tuple(1 if ch == 'R' else 2 if ch == 'Y' else 0 for ch in diagram)
        _LEAVES[key] = diagram
        _LEAVES[_mirror(key)] = ''.join(''.join(rows[r][::-1]) for r in range(6))


def _mirror(board):
    return tuple(board[r * 7 + c] for r in range(6) for c in range(6, -1, -1))


def _landings(board, rows=6, cols=7):
    return [(c, next(r * cols + c for r in range(rows - 1, -1, -1)
                     if board[r * cols + c] == 0))
            for c in range(cols) if board[c] == 0]


def _wins(board, index, mark, rows=6, cols=7, target=4):
    r, c = divmod(index, cols)
    for dr, dc in ((1, 0), (0, 1), (1, 1), (1, -1)):
        count = 1
        for sign in (-1, 1):
            rr, cc = r + sign * dr, c + sign * dc
            while 0 <= rr < rows and 0 <= cc < cols and board[rr * cols + cc] == mark:
                count += 1
                rr += sign * dr
                cc += sign * dc
        if count >= target:
            return True
    return False


def _policy(board, diagram):
    moves = _landings(board)
    for mark in (1, 2):
        for c, i in moves:
            if _wins(board, i, mark):
                return c
    for level in '0123456789abcd':
        choices = [c for c, i in moves if diagram[i] == level]
        if len(choices) == 1:
            return choices[0]
    return None


def _recover(board, deadline):
    """Recover a valid policy history if Kaggle reloads the module each turn.

    Matching only a subset of a diagram's disks is unsafe. Instead replay
    the actual Red policy and every Yellow reply compatible with the target.
    """
    target = tuple(board)
    failed = set()
    visits = 0

    def visit(state, diagram, mark):
        nonlocal visits
        visits += 1
        if visits % 128 == 0 and time.perf_counter() >= deadline:
            raise TimeoutError
        key = (state, diagram, mark)
        if key in failed:
            return None
        if state == target:
            if diagram is not None:
                move = _policy(state, diagram)
                return (move, diagram) if move is not None else None
            if state in _BOOK:
                return _BOOK[state], None
            if state in _LEAVES:
                d = _LEAVES[state]
                return _policy(state, d), d
            return None
        if mark == 1:
            if diagram is None:
                diagram = _LEAVES.get(state)
            move = _policy(state, diagram) if diagram is not None else _BOOK.get(state)
            choices = [(c, i) for c, i in _landings(state) if c == move]
        else:
            choices = _landings(state)
        for c, i in choices:
            if target[i] != mark or _wins(state, i, mark):
                continue
            child = list(state)
            child[i] = mark
            result = visit(tuple(child), diagram, 3 - mark)
            if result is not None:
                return result
        failed.add(key)
        return None

    return visit((0,) * 42, None, 1)


def _strategy(board, deadline):
    global _ACTIVE
    _load()
    key = tuple(board)
    # A cached diagram is valid only after our last move and one Yellow move.
    if _ACTIVE is not None:
        previous, diagram = _ACTIVE
        differences = [i for i in range(42) if previous[i] != board[i]]
        if len(differences) == 1:
            i = differences[0]
            if previous[i] == 0 and board[i] == 2 and (i // 7 == 5 or previous[i + 7]):
                move = _policy(board, diagram)
                if move is not None:
                    return move, diagram
    if key in _BOOK:
        return _BOOK[key], None
    if key in _LEAVES:
        diagram = _LEAVES[key]
        return _policy(board, diagram), diagram
    return _recover(board, deadline)


def _search(board, mark, rows, cols, target, deadline):
    """Iterative deepening negamax, bitboards, tactical pruning and a TT."""
    stride = rows + 1
    bottom = sum(1 << (c * stride) for c in range(cols))
    full = sum(((1 << rows) - 1) << (c * stride) for c in range(cols))
    masks = [((1 << rows) - 1) << (c * stride) for c in range(cols)]
    order = sorted(range(cols), key=lambda c: abs(c - (cols - 1) / 2))
    me = occupied = 0
    for r in range(rows):
        for c in range(cols):
            value = board[r * cols + c]
            bit = 1 << (c * stride + rows - 1 - r)
            if value:
                occupied |= bit
                if value == mark:
                    me |= bit
    shifts = (1, stride, stride - 1, stride + 1)

    def won(p):
        for shift in shifts:
            run = p
            for n in range(1, target):
                run &= p >> (shift * n)
            if run:
                return True
        return False

    def threats(p, occ):
        # All empty cells completing a line, including unplayable threats.
        if target == 4:
            result = (p << 1) & (p << 2) & (p << 3)
            for s in shifts[1:]:
                pair = (p << s) & (p << (2 * s))
                result |= pair & (p << (3 * s))
                result |= pair & (p >> s)
                pair = (p >> s) & (p >> (2 * s))
                result |= pair & (p << s)
                result |= pair & (p >> (3 * s))
            return result & (full ^ occ)
        return sum(1 << i for i in range(cols * stride)
                   if (full ^ occ) & (1 << i) and won(p | (1 << i)))

    def evaluate(p, occ):
        q = occ ^ p
        value = 40 * (threats(p, occ).bit_count() - threats(q, occ).bit_count())
        for s in shifts:
            value += 3 * ((p & (p >> s)).bit_count() - (q & (q >> s)).bit_count())
        for c in range(cols):
            weight = cols - abs(2 * c - cols + 1)
            value += weight * ((p & masks[c]).bit_count() - (q & masks[c]).bit_count())
        return value

    table = {}
    nodes = 0
    win = 100000

    def negamax(p, occ, depth, alpha, beta, ply):
        nonlocal nodes
        nodes += 1
        if nodes % 128 == 0 and time.perf_counter() >= deadline:
            raise TimeoutError
        possible = (occ + bottom) & full
        if not possible:
            return 0
        if threats(p, occ) & possible:
            return win - ply
        opponent_threats = threats(occ ^ p, occ)
        forced = possible & opponent_threats
        if forced:
            if forced & (forced - 1):
                return -win + ply + 1
            possible = forced
        possible &= ~(opponent_threats >> 1)
        if not possible:
            return -win + ply + 1
        if depth <= 0:
            return evaluate(p, occ)
        key = (p, occ)
        entry = table.get(key)
        original_alpha, original_beta = alpha, beta
        preferred = -1
        if entry is not None:
            old_depth, score, flag, preferred = entry
            if old_depth >= depth:
                if flag == 0:
                    return score
                if flag == 1:
                    alpha = max(alpha, score)
                else:
                    beta = min(beta, score)
                if alpha >= beta:
                    return score
        moves = []
        for c in order:
            bit = possible & masks[c]
            if bit:
                priority = 1000 if c == preferred else 0
                priority += threats(p | bit, occ | bit).bit_count()
                moves.append((priority, c, bit))
        moves.sort(key=lambda item: item[0], reverse=True)
        best, best_col = -2 * win, moves[0][1]
        for _, c, bit in moves:
            score = -negamax(occ ^ p, occ | bit, depth - 1, -beta, -alpha, ply + 1)
            if score > best:
                best, best_col = score, c
            alpha = max(alpha, best)
            if alpha >= beta:
                break
        if len(table) < 150000:
            flag = 2 if best <= original_alpha else 1 if best >= original_beta else 0
            table[key] = depth, best, flag, best_col
        return best

    possible = (occupied + bottom) & full
    choices = [(c, possible & masks[c]) for c in order if possible & masks[c]]
    best_col = choices[0][0]
    for depth in range(1, rows * cols - occupied.bit_count() + 1):
        if time.perf_counter() >= deadline:
            break
        scores = []
        alpha = -2 * win
        try:
            for c, bit in choices:
                if won(me | bit):
                    return c
                score = -negamax(occupied ^ me, occupied | bit, depth - 1,
                                 -2 * win, -alpha, 1)
                scores.append((score, c, bit))
                alpha = max(alpha, score)
        except TimeoutError:
            break
        scores.sort(key=lambda item: item[0], reverse=True)
        best_col = scores[0][1]
        choices = [(c, bit) for _, c, bit in scores]
        if abs(scores[0][0]) > win // 2:
            break
    return best_col


def agent(observation, configuration):
    """Kaggle entry point. Return a zero-based legal column."""
    global _ACTIVE, _LAST_MODE
    start = time.perf_counter()
    get = lambda obj, name, default: obj.get(name, default) if isinstance(obj, dict) else getattr(obj, name, default)
    board = list(get(observation, 'board', []))
    mark = int(get(observation, 'mark', 1))
    rows = int(get(configuration, 'rows', 6))
    cols = int(get(configuration, 'columns', 7))
    target = int(get(configuration, 'inarow', 4))
    timeout = float(get(configuration, 'actTimeout', 2))
    budget = max(0.001, min(1.65, timeout * 0.8))
    deadline = start + budget
    moves = _landings(board, rows, cols)
    if not moves:
        return 0  # Kaggle does not invoke agents on terminal boards.
    for player in (mark, 3 - mark):
        for c, i in moves:
            if _wins(board, i, player, rows, cols, target):
                # Continue updating policy state when a forced block is played.
                if player == mark or not (mark == 1 and (rows, cols, target) == (6, 7, 4)):
                    _LAST_MODE = 'tactic'
                    return int(c)
                break
    if mark == 1 and (rows, cols, target) == (6, 7, 4):
        try:
            result = _strategy(board, start + budget * 0.35)
        except TimeoutError:
            result = None
        if result is not None:
            c, diagram = result
            if c is not None and 0 <= c < cols and board[c] == 0:
                _ACTIVE = None
                if diagram is not None:
                    after = board[:]
                    after[next(i for col, i in moves if col == c)] = 1
                    _ACTIVE = tuple(after), diagram
                _LAST_MODE = 'weakc4'
                return int(c)
    _ACTIVE = None
    _LAST_MODE = 'search'
    # Always handle forced blocks before a timed search.
    for c, i in moves:
        if _wins(board, i, 3 - mark, rows, cols, target):
            return int(c)
    return int(_search(board, mark, rows, cols, target, deadline))
